// P1-A2: compare the VT state machine against a baseline, per case.
//
// The criterion asks for a per-case baseline comparison with the differences needing a
// human to confirm them. Two decisions shape this file:
//
//   * The baselines are generated by tmux, not by us. A baseline produced by our own
//     emulator would only prove that we did not change, and would happily lock in a bug.
//     tmux is an independent implementation of the same escape sequences, so a baseline it
//     produced is evidence about the sequences.
//
//   * The comparison is text, not a hash alone. A hash says "different"; the diff says
//     which cell moved, which is what a human needs in order to confirm a difference.
//
// The fixture corpus lives in tests/fixtures/vt as escaped byte streams, and the baselines
// live in tests/baselines/vt as the canonical screen snapshot. Regenerating the baselines
// is a deliberate act: set OPENCRT_VT_WRITE_BASELINES to a directory, run the test, and
// review the diff before committing it.

#include <gtest/gtest.h>

#include <algorithm>
#include <chrono>
#include <cstdint>
#include <cstdlib>
#include <filesystem>
#include <fstream>
#include <sstream>
#include <string>
#include <vector>

#include "protocols/local/LocalPtyChannel.h"
#include "support/VtReference.h"
#include "terminal/buffer/ScreenGrid.h"
#include "terminal/emulator/ScreenSnapshot.h"
#include "terminal/emulator/TerminalEmulator.h"

namespace {

namespace fs = std::filesystem;

using openscrt::terminal::ScreenGrid;
using openscrt::terminal::snapshotScreen;
using openscrt::terminal::TerminalEmulator;

constexpr int kRows = 24;
constexpr int kCols = 80;

const std::string kFixtureDirectory = std::string(OPENCRT_SOURCE_DIR) + "/tests/fixtures/vt";
const std::string kBaselineDirectory = std::string(OPENCRT_SOURCE_DIR) + "/tests/baselines/vt";

// Set by the writer below; when it is running, the comparison cases have nothing to
// compare against and would report a false failure.
bool g_writerRan = false;

// Decodes the escaped byte streams the fixtures are stored as.
//
// The format is deliberately readable: printable bytes stand for themselves, and the
// interesting ones are written as \xNN, \e, \n, \r, \t or \\. A reviewer can read a fixture
// and see the escape sequences without decoding anything.
std::vector<std::uint8_t> decodeFixture(const std::string& text) {
    std::vector<std::uint8_t> bytes;
    bytes.reserve(text.size());

    const auto hexDigit = [](char digit) -> int {
        if (digit >= '0' && digit <= '9') {
            return digit - '0';
        }
        if (digit >= 'a' && digit <= 'f') {
            return digit - 'a' + 10;
        }
        if (digit >= 'A' && digit <= 'F') {
            return digit - 'A' + 10;
        }
        return -1;
    };

    for (std::size_t i = 0; i < text.size(); ++i) {
        const char character = text[i];
        if (character != '\\' || i + 1 >= text.size()) {
            bytes.push_back(static_cast<std::uint8_t>(character));
            continue;
        }
        const char escape = text[++i];
        switch (escape) {
            case 'x': {
                if (i + 2 >= text.size()) {
                    bytes.push_back('\\');
                    bytes.push_back('x');
                    break;
                }
                const int high = hexDigit(text[i + 1]);
                const int low = hexDigit(text[i + 2]);
                if (high < 0 || low < 0) {
                    bytes.push_back('\\');
                    bytes.push_back('x');
                    break;
                }
                bytes.push_back(static_cast<std::uint8_t>(high * 16 + low));
                i += 2;
                break;
            }
            case 'e':
                bytes.push_back(0x1B);
                break;
            case 'n':
                bytes.push_back('\n');
                break;
            case 'r':
                bytes.push_back('\r');
                break;
            case 't':
                bytes.push_back('\t');
                break;
            case '\\':
                bytes.push_back('\\');
                break;
            default:
                bytes.push_back('\\');
                bytes.push_back(static_cast<std::uint8_t>(escape));
                break;
        }
    }
    return bytes;
}

std::string readFile(const fs::path& path) {
    std::ifstream stream(path, std::ios::binary);
    if (!stream) {
        return {};
    }
    std::ostringstream buffer;
    buffer << stream.rdbuf();
    return buffer.str();
}

std::vector<fs::path> listFixtures() {
    std::vector<fs::path> fixtures;
    std::error_code error;
    if (!fs::is_directory(kFixtureDirectory, error)) {
        return fixtures;
    }
    for (const fs::directory_entry& entry : fs::directory_iterator(kFixtureDirectory, error)) {
        if (!entry.is_regular_file()) {
            continue;
        }
        if (entry.path().extension() != ".esc") {
            continue;
        }
        fixtures.push_back(entry.path());
    }
    std::sort(fixtures.begin(), fixtures.end());
    return fixtures;
}

// The screen our own emulator ends up with.
std::string renderWithOurEmulator(const std::vector<std::uint8_t>& bytes) {
    ScreenGrid grid(kRows, kCols);
    TerminalEmulator emulator(grid);
    emulator.write(bytes.data(), bytes.size());
    return snapshotScreen(grid);
}

// Captures what a real program draws.
//
// The corpus in tests/fixtures is written by hand, which makes it readable but also makes
// it only as good as the author's imagination of what a terminal emits. Running the real
// programs and capturing their bytes answers a different question: does the emulator
// render what vim, htop and less actually draw the way tmux renders it?
//
// The capture stops when the program goes quiet, so the last sequence in it is complete.
// A capture cut in the middle of an escape sequence would be recovered differently by the
// two implementations, and that difference would be an artefact of the cut.
std::vector<std::uint8_t> captureProgram(const std::string& command,
                                         std::chrono::milliseconds budget) {
    openscrt::protocols::local::LocalPtyChannel::Options options;
    options.shell = "/bin/sh";
    options.arguments = {"-c", command};
    options.initial_size = openscrt::protocols::WindowSize{kRows, kCols};
    options.ring_capacity = 256 * 1024;

    openscrt::protocols::local::LocalPtyChannel channel{options};
    if (!channel.connectAsync().ok) {
        return {};
    }

    std::vector<std::uint8_t> captured;
    std::uint8_t buffer[4096];
    const auto deadline = std::chrono::steady_clock::now() + budget;
    while (std::chrono::steady_clock::now() < deadline) {
        const std::size_t read =
            channel.readAvailable(buffer, sizeof(buffer), std::chrono::milliseconds(200));
        if (read == 0) {
            if (!captured.empty()) {
                break;  // the program went quiet: its last sequence is complete
            }
            continue;  // nothing yet: keep waiting for it to start
        }
        captured.insert(captured.end(), buffer, buffer + read);
    }
    channel.disconnect();
    return captured;
}

// The programs the acceptance criterion names, with the terminal type they need to emit
// escape sequences at all.
std::vector<std::string> realProgramCommands() {
    return {
        "TERM=xterm-256color vim -u NONE -i NONE",
        // htop redraws on a timer. Ten seconds between redraws means the capture stops
        // after the first screen instead of catching one in the middle of a redraw.
        "TERM=xterm-256color htop -d 100",
        "TERM=xterm-256color less /etc/hostname",
    };
}

// Writes the raw capture next to the test's other output, so a difference can be
// diagnosed from the bytes rather than from the picture they produce.
void writeCapture(const std::string& command, const std::vector<std::uint8_t>& captured) {
    const char* directory = std::getenv("OPENCRT_VT_CAPTURE_DIR");
    if (directory == nullptr || directory[0] == '\0') {
        return;
    }
    std::error_code error;
    fs::create_directories(directory, error);

    // The command becomes a file name: everything that is not a letter, a digit or a dash
    // goes, and what is left is enough to tell the three apart.
    std::string name;
    for (const char character : command) {
        const bool plain = (character >= 'a' && character <= 'z') ||
                           (character >= 'A' && character <= 'Z') ||
                           (character >= '0' && character <= '9') || character == '-';
        name.push_back(plain ? character : '_');
    }
    const fs::path target = fs::path(directory) / (name + ".bin");
    std::ofstream stream(target, std::ios::binary | std::ios::trunc);
    stream.write(reinterpret_cast<const char*>(captured.data()),
                 static_cast<std::streamsize>(captured.size()));
}

// Prints the first differing lines, so a human sees what moved instead of a bare
// "not equal".
void reportDifference(const std::string& expected, const std::string& actual) {
    std::istringstream expectedStream(expected);
    std::istringstream actualStream(actual);
    std::string expectedLine;
    std::string actualLine;
    int lineNumber = 0;
    int reported = 0;

    while (true) {
        // Both streams have to be read every round. Chaining them with || short-circuits
        // on the first one that still has a line, which leaves the other side stale --
        // and a diff that shows an empty "ours" column is worse than no diff at all.
        const bool hasExpected = static_cast<bool>(std::getline(expectedStream, expectedLine));
        const bool hasActual = static_cast<bool>(std::getline(actualStream, actualLine));
        if (!hasExpected && !hasActual) {
            break;
        }
        ++lineNumber;
        if (hasExpected && hasActual && expectedLine == actualLine) {
            continue;
        }
        if (reported >= 10) {
            std::printf("  ... (more differences follow)\n");
            break;
        }
        std::printf("  line %d:\n    baseline: %s\n    ours:     %s\n", lineNumber,
                    hasExpected ? expectedLine.c_str() : "<missing>",
                    hasActual ? actualLine.c_str() : "<missing>");
        ++reported;
    }
}

// Regenerates the baselines with tmux. This runs as a global environment so it happens
// before the comparison cases, and it is opt-in: without the environment variable nothing
// is written.
class BaselineWriter : public ::testing::Environment {
    void SetUp() override {
        const char* directory = std::getenv("OPENCRT_VT_WRITE_BASELINES");
        if (directory == nullptr || directory[0] == '\0') {
            return;
        }
        if (!openscrt::test::tmuxAvailable()) {
            std::printf("tmux is not installed; the baselines cannot be regenerated\n");
            return;
        }

        std::error_code error;
        fs::create_directories(directory, error);

        const std::vector<fs::path> fixtures = listFixtures();
        for (const fs::path& fixture : fixtures) {
            const std::vector<std::uint8_t> bytes = decodeFixture(readFile(fixture));
            const std::string reference = openscrt::test::renderWithTmux(bytes, kRows, kCols);
            if (reference.empty()) {
                // path::c_str() is a wchar_t* on Windows, which %s will not take.
                std::printf("could not render %s through tmux\n",
                            fixture.filename().string().c_str());
                continue;
            }
            const fs::path target = fs::path(directory) / (fixture.stem().string() + ".txt");
            std::ofstream stream(target, std::ios::binary | std::ios::trunc);
            stream << reference;
            std::printf("wrote %s\n", target.string().c_str());
        }
        g_writerRan = true;
    }
};

}  // namespace

int main(int argc, char** argv) {
    ::testing::AddGlobalTestEnvironment(new BaselineWriter);
    ::testing::InitGoogleTest(&argc, argv);
    return RUN_ALL_TESTS();
}

namespace {

TEST(VtBaselineTest, TheCorpusIsNotEmpty) {
    // An empty corpus would make every other case in this file pass vacuously, which is
    // the classic way a baseline gate stops gating anything.
    EXPECT_FALSE(listFixtures().empty()) << "no fixtures found in " << kFixtureDirectory
                                         << "; the baseline gate would be checking nothing";
}

TEST(VtBaselineTest, EveryFixtureMatchesItsBaseline) {
    if (g_writerRan) {
        GTEST_SKIP() << "the baselines are being regenerated in this run";
    }

    const std::vector<fs::path> fixtures = listFixtures();
    ASSERT_FALSE(fixtures.empty());

    for (const fs::path& fixture : fixtures) {
        const std::vector<std::uint8_t> bytes = decodeFixture(readFile(fixture));
        ASSERT_FALSE(bytes.empty()) << fixture.filename() << " decoded to nothing";

        const std::string ours = renderWithOurEmulator(bytes);

        const fs::path baseline = fs::path(kBaselineDirectory) / (fixture.stem().string() + ".txt");
        ASSERT_TRUE(fs::exists(baseline))
            << "no baseline for " << fixture.filename() << "; expected " << baseline.string()
            << ". Regenerate with OPENCRT_VT_WRITE_BASELINES=<dir> and review the result";

        const std::string expected = readFile(baseline);
        ASSERT_FALSE(expected.empty()) << baseline.string() << " is empty";

        if (expected != ours) {
            ADD_FAILURE() << fixture.filename() << " does not match its baseline";
            reportDifference(expected, ours);
        }
    }
}

TEST(VtBaselineTest, RealProgramOutputRendersTheWayTmuxRendersIt) {
    if (!openscrt::test::tmuxAvailable()) {
        GTEST_SKIP() << "tmux is not installed";
    }

    int compared = 0;
    for (const std::string& command : realProgramCommands()) {
        const std::vector<std::uint8_t> captured =
            captureProgram(command, std::chrono::milliseconds(4000));
        // A program that is not installed here prints a shell error message, and that
        // message contains no escape sequences. That is the signal to skip it.
        const bool drewSomething = std::any_of(captured.begin(), captured.end(),
                                               [](std::uint8_t byte) { return byte == 0x1B; });
        if (!drewSomething) {
            continue;
        }
        writeCapture(command, captured);

        const std::string ours = renderWithOurEmulator(captured);
        const std::string theirs = openscrt::test::renderWithTmux(captured, kRows, kCols);
        if (theirs.empty()) {
            continue;
        }
        ++compared;
        if (ours != theirs) {
            ADD_FAILURE() << "the capture of '" << command << "' renders differently";
            reportDifference(theirs, ours);
        }
    }

    // On the Linux runner the programs are installed, so a capture that produced nothing
    // there means the comparison quietly stopped testing anything. Elsewhere the count is
    // only informational -- and it is printed, so the variable is not unused anywhere.
    std::printf("[vt] %d real program capture(s) compared against tmux\n", compared);
#if defined(__linux__)
    EXPECT_GT(compared, 0) << "no real program produced any output";
#endif
}

}  // namespace
